using Microsoft.CodeAnalysis;

namespace S7.Generator;

/// <summary>
/// Emits code that breaks many style rules, to check that auto-generated output is excluded from style analysis.
/// </summary>
[Generator]
public sealed class StyleViolatingGenerator : IIncrementalGenerator
{
    private const string Source = """
        // <auto-generated/>
        #nullable enable
        using System.Collections.Generic;
        using System;
        namespace S7.Consumer {
        public class generated_channels_spec
        {
            public string field_without_docs = "x";
            public int count;
            public static List<string> Names() { var l = new List<string>(); if (l.Count == 0) l.Add("api"); return l; }
            public bool Same(string a, string b) => a == b.ToLower();
            public DateTime When() => DateTime.UnixEpoch;
        }
        }
        """;

    /// <inheritdoc/>
    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        context.RegisterPostInitializationOutput(static ctx => ctx.AddSource("Generated.g.cs", Source));
    }
}
